"""Offline regression tests using independently checked source-value fixtures."""
import csv
import hashlib
import json
import os
import sys
import unittest
from collections import Counter
from decimal import Decimal
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
import analysis

SOURCE_SHA256 = 'f7e31557b30b933c2d99029c8811a532ab3f3046a8f8c7cf4f240a27e8f2de46'

# Independent workbook audit: delta, median delta, one-omission minimum/maximum.
# Constants were checked with decimal sums, not generated by analysis.py.
KNOWN = {
    ('liver', 'PD1'): (1.0786666666666667, 9.4, -.3222857142857143, 2.901666666666667),
    ('liver', 'CTLA4'): (-11.788666666666666, -8.9, -13.259571428571428, -9.851),
    ('liver', 'ICOS'): (-38.92933333333333, -45.9, -41.55171428571428, -37.68333333333333),
    ('liver', 'IFNg'): (-18.983333333333334, -21.2, -20.87457142857143, -17.603857142857144),
    ('liver', 'Tetramer abundance'): (2.7733333333333334, 5.5, 1.289047619047619, 4.662857142857143),
    ('dt', 'PD1'): (-13.81, -17.15, -17.38222222222222, -11.45),
    ('dt', 'CTLA4'): (7.58, 6.7, 5.054444444444444, 9.825555555555555),
    ('dt', 'ICOS'): (19.73, 26.45, 16.225555555555555, 23.392222222222223),
    ('dt', 'IFNg'): (10.333, 15.47, 9.146888888888888, 13.84688888888889),
    ('dt', 'Tetramer abundance'): (5.721, 6.62, 2.0523333333333333, 7.858666666666666),
    ('9h10', 'PD1'): (-4.5, -5.0, -6.844444444444444, -2.6222222222222222),
    ('9h10', 'CTLA4'): (2.62, 7.0, .4922222222222222, 5.283333333333333),
    ('9h10', 'ICOS'): (32.3, 33.0, 30.622222222222224, 34.06666666666667),
    ('9h10', 'IFNg'): (16.308, 18.0, 14.245777777777779, 17.804444444444446),
    ('9h10', 'Tetramer abundance'): (3.73, -4.8, .9522222222222222, 5.488888888888889),
    ('ezh2', 'PD1'): (-.2, -2.0, -1.995, 1.205),
    ('ezh2', 'CTLA4'): (5.92, 3.6, 2.515, 8.94),
    ('ezh2', 'ICOS'): (18.98, 13.9, 15.63, 21.905),
    ('ezh2', 'IFNg'): (13.8, 11.0, 10.8, 16.05),
    ('ezh2', 'Tetramer abundance'): (1.96, 4.3, -6.375, 8.325),
}


class AnalysisTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.data = json.loads((ROOT / 'analysis.json').read_text())
        with (ROOT / 'observations.csv').open(newline='') as handle:
            cls.rows = list(csv.DictReader(handle))

    def test_coverage_and_unique_source_cells(self):
        self.assertEqual(len(self.rows), 400)
        self.assertEqual(len(self.data['results']), 20)
        self.assertEqual(Counter(r['contrast'] for r in self.rows),
                         {'liver': 150, 'dt': 100, '9h10': 100, 'ezh2': 50})
        self.assertEqual(len({(r['source_sheet'], r['source_cell']) for r in self.rows}), 400)
        self.assertEqual(self.data['provenance']['source_sha256'], SOURCE_SHA256)
        self.assertEqual(self.data['provenance']['record_count'], 400)
        self.assertEqual(self.data['provenance']['source_bytes'], 74411)
        for row in self.rows:
            self.assertTrue(Decimal(0) <= Decimal(row['value']) <= Decimal(100))

    def test_all_known_differences_and_sensitivity_extrema(self):
        self.assertEqual({(r['contrast'], r['marker']) for r in self.data['results']}, set(KNOWN))
        for result in self.data['results']:
            key = (result['contrast'], result['marker'])
            recalculated = analysis.summarize(result['groups']['a'], result['groups']['b'])
            for field, expected in zip(('delta', 'median_delta', 'loo_min', 'loo_max'), KNOWN[key]):
                with self.subTest(key=key, field=field):
                    self.assertAlmostEqual(result[field], expected, delta=1e-12)
                    self.assertAlmostEqual(recalculated[field], expected, delta=1e-12)

    def test_means_counts_and_csv_json_mapping(self):
        expected_rows = []
        counts = {'liver': 15, 'dt': 10, '9h10': 10, 'ezh2': 5}
        for result in self.data['results']:
            for group in ('a', 'b'):
                records = result['groups'][group]
                self.assertEqual(len(records), counts[result['contrast']])
                self.assertEqual(result['n_' + group], len(records))
                values = [Decimal(str(record['value'])) for record in records]
                self.assertAlmostEqual(result['mean_' + group], float(sum(values) / len(values)), delta=1e-12)
                expected_rows.extend(dict(contrast=result['contrast'], marker=result['marker'],
                                          denominator=result['denominator'], **record) for record in records)
        actual_rows = [dict(row, value=float(row['value'])) for row in self.rows]
        self.assertEqual(actual_rows, expected_rows)

    def test_direction_and_denominator_mapping(self):
        labels = {'liver': ('SQ only', 'SQ + liver'), 'dt': ('DT−', 'DT+'),
                  '9h10': ('Isotype', '9H10'), 'ezh2': ('Anti-PD-1', 'CPI-1205 + anti-PD-1')}
        for result in self.data['results']:
            for group, label in zip(('a', 'b'), labels[result['contrast']]):
                self.assertEqual({r['group'] for r in result['groups'][group]}, {label})
            denominator = 'CD8+ T cells' if result['marker'] == 'Tetramer abundance' else 'KSP-tetramer+ CD8+ T cells'
            self.assertEqual(result['denominator'], denominator)
            self.assertEqual(result['unit'], 'percentage points')

    def test_provisional_shortlist(self):
        self.assertEqual(analysis.candidates(self.data, 5, True), ['ICOS', 'IFNg'])
        self.assertEqual(analysis.candidates(self.data, 10, True), ['ICOS'])
        self.assertEqual(analysis.candidates(self.data, 10, False), ['ICOS', 'IFNg'])
        self.assertEqual(analysis.candidates(self.data, 20, True), [])

    def test_single_observation_not_paired_omission(self):
        summary = analysis.summarize([{'value': 0}, {'value': 10}], [{'value': 20}, {'value': 40}])
        expected = dict(mean_a=5, mean_b=30, delta=25, median_delta=25, loo_min=15, loo_max=35, n_a=2, n_b=2)
        self.assertEqual(summary, expected)

    def test_local_workbook_when_available(self):
        supplied = os.environ.get('LEE_SOURCE_WORKBOOK')
        source = Path(supplied) if supplied else ROOT / 'source-cache' / 'TableS1.xlsx'
        if not supplied and not source.exists():
            self.skipTest('Source workbook is not redistributed; run analysis.py to obtain it separately.')
        self.assertEqual(hashlib.sha256(source.read_bytes()).hexdigest(), SOURCE_SHA256)
        extracted, rows = analysis.extract(source)
        self.assertEqual(extracted, self.data)
        self.assertEqual(rows, [dict(row, value=float(row['value'])) for row in self.rows])


if __name__ == '__main__':
    unittest.main()
